def audit_source():
    imports = "\n".join("import " + name[:-5] for name in SOURCE_NAMES)
    body = [imports, "universe u v w x y z u_1 u_2 u_3 u_4 u_5 u_6",
            "open TypedPathsV11", "attribute [local instance] Classical.propDecidable"]
    for i, (target, signature) in enumerate(ENTRIES):
        if target in TAIL_TARGETS:
            body.append(f"noncomputable def registered_{i} {signature}")
        else:
            rhs = target + ".{u_1,u_2,u_3,u_4}" if target == "ProcessMapsV26.ProcessMap" else target
            body.append(f"noncomputable def registered_{i} : {signature} := @{rhs}")
        body.append(f"#print axioms registered_{i}")
    return "\n".join(body) + "\n"
